<script setup lang="ts">
import type { JobSnapshot, ProcessSnapshot } from '../types/api'
const api = useApi(); const hub = useActivity(); const store = useActivityStore(); const connected = ref(true); const subscriptions: (() => void)[] = []
onMounted(() => { for (const job of store.jobs.value) if (['queued', 'running', 'stopping'].includes(job.status)) subscriptions.push(hub.subscribe('job', job.id, () => refreshJob(job.id))); for (const process of store.processes.value) if (['running', 'stopping'].includes(process.status)) subscriptions.push(hub.subscribe('process', process.id, () => refreshProcess(process.id))) })
onBeforeUnmount(() => subscriptions.splice(0).forEach((unsubscribe) => unsubscribe()))
async function refreshJob(id: string) { try { store.trackJob(await api.get<JobSnapshot>(`/jobs/${id}`)); connected.value = true } catch { connected.value = false } }
async function refreshProcess(id: string) { try { store.trackProcess(await api.get<ProcessSnapshot>(`/processes/${id}`)); connected.value = true } catch { connected.value = false } }
async function cancel(id: string) { store.trackJob(await api.post<JobSnapshot>(`/jobs/${id}/cancel`)) }
</script>
<template><section class="page-sheet"><header class="page-header"><div><p class="eyebrow">Session ledger</p><h1>Activity</h1><p>Finite provisioning jobs and managed site processes started from this UI session.</p></div><span class="status-lozenge"><span class="signal" :class="{ 'signal--waiting': !connected }" />{{ connected ? 'Streams live' : 'Reconnecting' }}</span></header><div v-if="store.jobs.value.length || store.processes.value.length" class="activity-stack"><section v-if="store.processes.value.length"><p class="eyebrow">Managed processes</p><article v-for="process in store.processes.value" :key="process.id" class="activity-detail"><header><div><h2>{{ process.siteId }} · {{ process.taskId }}</h2><code>{{ process.id }}</code></div><span class="status-lozenge">{{ process.status }}</span></header><div class="url-list"><a v-for="url in process.urls" :key="url" :href="url" target="_blank" rel="noreferrer">{{ url }} ↗</a></div><LogViewer :events="process.events" :connected="connected" /></article></section><section v-if="store.jobs.value.length"><p class="eyebrow">Finite jobs</p><div v-for="job in store.jobs.value" :key="job.id" class="activity-detail"><JobStatus :job="job" @cancel="cancel" /><LogViewer :events="job.events" :connected="connected" /></div></section></div><div v-else class="empty-state"><h2>No activity in this session.</h2><p>Provision a workspace, site, or layer—or run a site task—to populate the ledger.</p></div></section></template>
